    LinkedList list = new LinkedList();
    list.addNode(1);
    list.addNode(2);
    list.addNode(3);
    list.addNode(4);
    list.addNode(5);

    Node middle = list.findMiddleNode();
    System.out.println("Middle node data: " + middle.data); // Output: 3
}
```

